UPDATE AHI_ALERT_TRACKING SET PRF_COLLECTION= #{prfCollection,jdbcType=VARCHAR}, LAST_UPDATED_BY= #{lastUpdatedBy,jdbcType=VARCHAR}, LAST_UPDATED_DATE=SYSDATE
, ALERT_COMPLETED_BY= #{alertCompletedBy,jdbcType=VARCHAR}, ALERT_COMPLETED_DATE=SYSDATE
WHERE AHI_ALERT_SEQ_ID = #{ahiAlertSeqId}

UPDATE AHI_ALERT_TRACKING
SET AHI_ALERT_STATUS= 'REVIEWED', AHI_ALERT_REVIEWED_BY= #{ahiAlertReviewedBy,jdbcType=VARCHAR}, AHI_ALERT_REVIEWED_DATE=SYSDATE
WHERE AHI_ALERT_SEQ_ID = #{ahiAlertSeqId}
